-- Catálogo completo 2026/27 obtenido de las plantillas públicas de LALIGA y Liga F.

alter table public.players add column if not exists photo_url text;
alter table public.players add column if not exists source_name text;
alter table public.players add column if not exists source_updated_at timestamptz;

create temporary table _nexo_official_player_seed (
  provider_id text, competition_id text, player_name text, position text, club_name text,
  market_value numeric, photo_url text, source_name text
) on commit drop;


update public.players
set active = false, updated_at = now()
where (provider_id is null and catalog_version = '2026-08-08')
   or provider_id like 'laliga:%' or provider_id like 'ligaf:%';

select competition_id || '_' || substr(md5(club_name), 1, 12), competition_id, club_name, true
from _nexo_official_player_seed group by competition_id, club_name
on conflict (competition_id, name) do update set active = true;

  id, competition_id, sports_club_id, provider_id, name, initials, position, market_value, active,
  catalog_version, photo_url, source_name, source_updated_at
)
select replace(seed.provider_id, ':', '_'), seed.competition_id, club.id, seed.provider_id, seed.player_name,
  upper(left(regexp_replace(seed.player_name, '[^[:alnum:]]', '', 'g'), 2)), seed.position, seed.market_value, true,
  '2026-08-09', seed.photo_url, seed.source_name, now()
from _nexo_official_player_seed seed
join public.sports_clubs club on club.competition_id = seed.competition_id and club.name = seed.club_name
on conflict (id) do update set competition_id = excluded.competition_id, sports_club_id = excluded.sports_club_id,
  provider_id = excluded.provider_id, name = excluded.name, initials = excluded.initials, position = excluded.position,
  market_value = excluded.market_value, active = true, catalog_version = excluded.catalog_version,
  photo_url = excluded.photo_url, source_name = excluded.source_name, source_updated_at = now();
